class Solution {
public:
    bool canTransform(string start, string result) {
        string s, r;
        vector<int> si, ri;
        for (int k = 0; k < (int)start.size(); k++)
            if (start[k] != 'X') { s += start[k]; si.push_back(k); }
        for (int k = 0; k < (int)result.size(); k++)
            if (result[k] != 'X') { r += result[k]; ri.push_back(k); }
        if (s != r) return false;
        for (int k = 0; k < (int)s.size(); k++) {
            if (s[k] == 'L' && si[k] < ri[k]) return false;
            if (s[k] == 'R' && si[k] > ri[k]) return false;
        }
        return true;
    }
};

