class Solution {
    public boolean canTransform(String start, String result) {
        StringBuilder s = new StringBuilder(), r = new StringBuilder();
        List<Integer> si = new ArrayList<>(), ri = new ArrayList<>();
        for (int k = 0; k < start.length(); k++)
            if (start.charAt(k) != 'X') { s.append(start.charAt(k)); si.add(k); }
        for (int k = 0; k < result.length(); k++)
            if (result.charAt(k) != 'X') { r.append(result.charAt(k)); ri.add(k); }
        if (!s.toString().equals(r.toString())) return false;
        for (int k = 0; k < s.length(); k++) {
            char c = s.charAt(k);
            if (c == 'L' && si.get(k) < ri.get(k)) return false;
            if (c == 'R' && si.get(k) > ri.get(k)) return false;
        }
        return true;
    }
}

